const SIMPLE_NEGATIVE_NUMBER_PATTERN = /^-(?:\d+|\d*\.\d+)$/;
const FLOAT_PATTERN =
  /^(?:\d(?:_?\d)*(?:\.(?:\d(?:_?\d)*)?)?|\.(?:\d(?:_?\d)*))(?:[eE][+-]?\d(?:_?\d)*)?$/;
const INF_OR_NAN_PATTERN = /^(?:inf(?:inity)?|nan)$/i;

export function isArgparseNegativeNumberToken(token) {
  return SIMPLE_NEGATIVE_NUMBER_PATTERN.test(token);
}

export function parsePythonFloat(rawValue) {
  if (typeof rawValue !== 'string' || rawValue.length === 0) {
    throw new Error('invalid float');
  }

  const sign =
    rawValue[0] === '+' || rawValue[0] === '-' ? rawValue[0] : '';
  const body = sign ? rawValue.slice(1) : rawValue;

  if (body.length === 0) {
    throw new Error('invalid float');
  }

  if (INF_OR_NAN_PATTERN.test(body)) {
    const normalized = body.toLowerCase();
    if (normalized === 'nan') {
      return Number.NaN;
    }

    return sign === '-' ? Number.NEGATIVE_INFINITY : Number.POSITIVE_INFINITY;
  }

  if (!FLOAT_PATTERN.test(body)) {
    throw new Error('invalid float');
  }

  const normalized = `${sign}${body.replaceAll('_', '')}`;
  const value = Number(normalized);

  if (Number.isNaN(value)) {
    throw new Error('invalid float');
  }

  return value;
}

