import {
  isArgparseNegativeNumberToken,
  parsePythonFloat,
} from './python-float.mjs';

const WIDTH = 78;
const HELP_OPTION = {
  name: '--help',
  display: '-h/--help',
  required: false,
  takesValue: false,
};
const OPTION_SPECS = [
  HELP_OPTION,
  {
    name: '--amount1',
    required: true,
    takesValue: true,
    type: 'float',
  },
  {
    name: '--amount2',
    required: true,
    takesValue: true,
    type: 'float',
  },
  {
    name: '--currency',
    required: true,
    takesValue: true,
    type: 'string',
  },
];
const REQUIRED_OPTIONS = OPTION_SPECS.filter((option) => option.required);
const USAGE_PARTS = [
  '[-h]',
  '--amount1 AMOUNT1',
  '--amount2 AMOUNT2',
  '--currency',
  'CURRENCY',
];

function basename(filePath) {
  if (!filePath) {
    return 'test19.mjs';
  }

  const normalizedPath = String(filePath).replace(/\\/g, '/');
  const lastSlash = normalizedPath.lastIndexOf('/');

  return lastSlash === -1 ? normalizedPath : normalizedPath.slice(lastSlash + 1);
}

function buildUsage(programName) {
  const prefix = `usage: ${programName}`;
  const continuationPrefix = ' '.repeat(prefix.length + 1);
  const lines = [];
  let currentLine = prefix;

  for (const part of USAGE_PARTS) {
    const candidate = `${currentLine} ${part}`;

    if (candidate.length > WIDTH && currentLine !== prefix) {
      lines.push(currentLine);
      currentLine = `${continuationPrefix}${part}`;
      continue;
    }

    currentLine = candidate;
  }

  lines.push(currentLine);

  return lines.join('\n');
}

function buildHelp(programName) {
  return `${buildUsage(programName)}\n\noptions:\n  -h, --help           show this help message and exit\n  --amount1 AMOUNT1\n  --amount2 AMOUNT2\n  --currency CURRENCY\n`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}\n${programName}: error: ${message}\n`;
}

function resolveLongOption(token) {
  const exactMatch = OPTION_SPECS.find((option) => option.name === token);

  if (exactMatch) {
    return { kind: 'match', option: exactMatch };
  }

  const matches = OPTION_SPECS.filter((option) => option.name.startsWith(token));

  if (matches.length === 0) {
    return { kind: 'unknown' };
  }

  if (matches.length > 1) {
    return { kind: 'ambiguous', matches };
  }

  return { kind: 'match', option: matches[0] };
}

function parseOptionValue(option, rawValue) {
  if (option.type === 'float') {
    try {
      return parsePythonFloat(rawValue);
    } catch {
      throw new Error(`argument ${option.name}: invalid float value: '${rawValue}'`);
    }
  }

  return rawValue;
}

export class ParserExit extends Error {
  constructor(code, stdout = '', stderr = '') {
    super(`Parser exited with code ${code}`);
    this.name = 'ParserExit';
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

export function parseArguments(argv, programPath) {
  const programName = basename(programPath);
  const values = new Map();
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h') {
      throw new ParserExit(0, buildHelp(programName));
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const attachedValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const resolution = resolveLongOption(optionToken);

      if (resolution.kind === 'ambiguous') {
        const matches = resolution.matches.map((option) => option.name).join(', ');
        throw new ParserExit(
          2,
          '',
          buildError(
            programName,
            `ambiguous option: ${optionToken} could match ${matches}`,
          ),
        );
      }

      if (resolution.kind === 'unknown') {
        extras.push(token);
        continue;
      }

      const option = resolution.option;

      if (!option.takesValue) {
        if (attachedValue !== null) {
          throw new ParserExit(
            2,
            '',
            buildError(
              programName,
              `argument ${option.display}: ignored explicit argument '${attachedValue}'`,
            ),
          );
        }

        throw new ParserExit(0, buildHelp(programName));
      }

      let rawValue = attachedValue;

      if (rawValue === null) {
        const nextToken = argv[index + 1];

        if (
          nextToken === undefined ||
          (nextToken.startsWith('-') &&
            !isArgparseNegativeNumberToken(nextToken))
        ) {
          throw new ParserExit(
            2,
            '',
            buildError(programName, `argument ${option.name}: expected one argument`),
          );
        }

        rawValue = nextToken;
        index += 1;
      }

      try {
        values.set(option.name, parseOptionValue(option, rawValue));
      } catch (error) {
        throw new ParserExit(2, '', buildError(programName, error.message));
      }

      continue;
    }

    extras.push(token);
  }

  const missing = REQUIRED_OPTIONS.filter((option) => !values.has(option.name)).map(
    (option) => option.name,
  );

  if (missing.length > 0) {
    throw new ParserExit(
      2,
      '',
      buildError(
        programName,
        `the following arguments are required: ${missing.join(', ')}`,
      ),
    );
  }

  if (extras.length > 0) {
    throw new ParserExit(
      2,
      '',
      buildError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    );
  }

  return {
    amount1: values.get('--amount1'),
    amount2: values.get('--amount2'),
    currency: values.get('--currency'),
  };
}

