import { CURRENCY_DATA } from './currency-data.mjs';
import {
  DecimalInvalidOperationError,
  compareNumericAmounts,
  createNumericAmount,
  formatNumericAmount,
} from './decimal.mjs';

const NBSP = '\u00a0';

export class CurrencyDoesNotExistError extends Error {
  constructor(code) {
    const normalizedCode = String(code).toUpperCase();
    super(
      `moneyed.classes.CurrencyDoesNotExist: No currency with code ${normalizedCode} is defined.`,
    );
    this.name = 'CurrencyDoesNotExistError';
  }
}

function getCurrency(code) {
  const normalizedCode = String(code).toUpperCase();
  const currency = CURRENCY_DATA[normalizedCode];

  if (!currency) {
    throw new CurrencyDoesNotExistError(normalizedCode);
  }

  return {
    code: normalizedCode,
    symbol: currency.symbol,
    decimals: currency.decimals,
  };
}

export class Money {
  constructor(amount, currency) {
    this.amount = createNumericAmount(amount);
    this.currency = getCurrency(currency);
  }

  isLessThan(other) {
    if (this.currency.code !== other.currency.code) {
      throw new Error('Cannot compare money values with different currencies.');
    }

    return compareNumericAmounts(this.amount, other.amount) < 0;
  }

  toString() {
    const amountText = formatNumericAmount(this.amount, this.currency.decimals);

    if (amountText.startsWith('-')) {
      return `-${this.currency.symbol}${NBSP}${amountText.slice(1)}`;
    }

    return `${this.currency.symbol}${NBSP}${amountText}`;
  }
}

