function normalizeFinite(digits, scale) {
  let normalizedDigits = digits.replace(/^0+/, '');
  let normalizedScale = scale;

  if (normalizedDigits.length === 0) {
    return { digits: '0', scale: 0 };
  }

  while (normalizedScale > 0 && normalizedDigits.endsWith('0')) {
    normalizedDigits = normalizedDigits.slice(0, -1);
    normalizedScale -= 1;
  }

  if (normalizedDigits.length === 0) {
    return { digits: '0', scale: 0 };
  }

  return { digits: normalizedDigits, scale: normalizedScale };
}

function parseFiniteNumberText(text) {
  const exponentIndex = text.search(/[eE]/);
  const significand =
    exponentIndex === -1 ? text : text.slice(0, exponentIndex);
  const exponent = exponentIndex === -1 ? 0 : Number(text.slice(exponentIndex + 1));
  const dotIndex = significand.indexOf('.');
  const integerPart = dotIndex === -1 ? significand : significand.slice(0, dotIndex);
  const fractionPart = dotIndex === -1 ? '' : significand.slice(dotIndex + 1);
  let digits = `${integerPart}${fractionPart}`;
  let scale = fractionPart.length - exponent;

  if (scale < 0) {
    digits += '0'.repeat(-scale);
    scale = 0;
  }

  return normalizeFinite(digits, scale);
}

function compareAlignedIntegerStrings(left, right) {
  if (left.length !== right.length) {
    return left.length < right.length ? -1 : 1;
  }

  if (left === right) {
    return 0;
  }

  return left < right ? -1 : 1;
}

function compareAbsoluteFinite(left, right) {
  const targetScale = Math.max(left.scale, right.scale);
  const leftAligned = left.digits + '0'.repeat(targetScale - left.scale);
  const rightAligned = right.digits + '0'.repeat(targetScale - right.scale);

  return compareAlignedIntegerStrings(leftAligned, rightAligned);
}

function incrementIntegerString(value) {
  let carry = 1;
  let result = '';

  for (let index = value.length - 1; index >= 0; index -= 1) {
    const nextDigit = value.charCodeAt(index) - 48 + carry;
    if (nextDigit === 10) {
      result = `0${result}`;
      carry = 1;
    } else {
      result = `${String.fromCharCode(48 + nextDigit)}${result}`;
      carry = 0;
    }
  }

  if (carry === 1) {
    result = `1${result}`;
  }

  return result;
}

function shouldRoundHalfEven(head, discarded) {
  const firstDiscarded = discarded[0];

  if (firstDiscarded > '5') {
    return true;
  }

  if (firstDiscarded < '5') {
    return false;
  }

  if (/[1-9]/.test(discarded.slice(1))) {
    return true;
  }

  const lastKept = head[head.length - 1] ?? '0';

  return (lastKept.charCodeAt(0) - 48) % 2 === 1;
}

function roundFiniteToScale(amount, targetScale) {
  if (amount.digits === '0') {
    return {
      kind: 'finite',
      negative: amount.negative,
      digits: '0',
      scale: targetScale,
    };
  }

  if (amount.scale <= targetScale) {
    return {
      kind: 'finite',
      negative: amount.negative,
      digits: amount.digits + '0'.repeat(targetScale - amount.scale),
      scale: targetScale,
    };
  }

  const cut = amount.scale - targetScale;
  const workingDigits = amount.digits.padStart(cut + 1, '0');
  const splitIndex = workingDigits.length - cut;
  let head = workingDigits.slice(0, splitIndex);
  const discarded = workingDigits.slice(splitIndex);

  if (shouldRoundHalfEven(head, discarded)) {
    head = incrementIntegerString(head);
  }

  const normalizedHead = head.replace(/^0+/, '') || '0';

  return {
    kind: 'finite',
    negative: amount.negative,
    digits: normalizedHead,
    scale: targetScale,
  };
}

function fixedPointText(digits, scale) {
  if (scale === 0) {
    return digits;
  }

  const paddedDigits = digits.padStart(scale + 1, '0');
  const integerPart = paddedDigits.slice(0, -scale);
  const fractionPart = paddedDigits.slice(-scale);

  return `${integerPart}.${fractionPart}`;
}

export class DecimalInvalidOperationError extends Error {
  constructor() {
    super("decimal.InvalidOperation: [<class 'decimal.InvalidOperation'>]");
    this.name = 'DecimalInvalidOperationError';
  }
}

export function createNumericAmount(value) {
  if (Number.isNaN(value)) {
    return { kind: 'nan' };
  }

  if (value === Number.POSITIVE_INFINITY || value === Number.NEGATIVE_INFINITY) {
    return { kind: 'infinity', negative: value < 0 };
  }

  const negative = value < 0 || Object.is(value, -0);
  const absoluteText = Math.abs(value).toString();
  const finite = parseFiniteNumberText(absoluteText);

  return {
    kind: 'finite',
    negative,
    digits: finite.digits,
    scale: finite.scale,
  };
}

export function compareNumericAmounts(left, right) {
  if (left.kind === 'nan' || right.kind === 'nan') {
    throw new DecimalInvalidOperationError();
  }

  if (left.kind === 'infinity' || right.kind === 'infinity') {
    if (left.kind === 'infinity' && right.kind === 'infinity') {
      if (left.negative === right.negative) {
        return 0;
      }

      return left.negative ? -1 : 1;
    }

    if (left.kind === 'infinity') {
      return left.negative ? -1 : 1;
    }

    return right.negative ? 1 : -1;
  }

  const leftNegative = left.negative && left.digits !== '0';
  const rightNegative = right.negative && right.digits !== '0';

  if (left.digits === '0' && right.digits === '0') {
    return 0;
  }

  if (leftNegative !== rightNegative) {
    return leftNegative ? -1 : 1;
  }

  const absoluteComparison = compareAbsoluteFinite(left, right);

  return leftNegative ? -absoluteComparison : absoluteComparison;
}

export function formatNumericAmount(amount, scale) {
  if (amount.kind === 'nan') {
    return 'NaN';
  }

  if (amount.kind === 'infinity') {
    return amount.negative ? '-INF' : 'INF';
  }

  const rounded = roundFiniteToScale(amount, scale);
  const text = fixedPointText(rounded.digits, scale);

  return rounded.negative ? `-${text}` : text;
}

